CREATE TABLE public.mensagens_globais (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, conteudo text NOT NULL CHECK (char_length(btrim(conteudo)) BETWEEN 1 AND 500), criado_em timestamptz NOT NULL DEFAULT now(), apagada boolean NOT NULL DEFAULT false);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.mensagens_globais TO authenticated; GRANT ALL ON public.mensagens_globais TO service_role;
ALTER TABLE public.mensagens_globais ENABLE ROW LEVEL SECURITY;
CREATE POLICY global_read ON public.mensagens_globais FOR SELECT TO authenticated USING (auth.uid() IS NOT NULL);
CREATE POLICY global_insert ON public.mensagens_globais FOR INSERT TO authenticated WITH CHECK (user_id=auth.uid());
CREATE POLICY global_update ON public.mensagens_globais FOR UPDATE TO authenticated USING (user_id=auth.uid()) WITH CHECK (user_id=auth.uid());
CREATE POLICY global_delete ON public.mensagens_globais FOR DELETE TO authenticated USING (user_id=auth.uid());
CREATE TABLE public.bloqueios (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), quem_bloqueou uuid NOT NULL, bloqueado uuid NOT NULL, criado_em timestamptz NOT NULL DEFAULT now(), UNIQUE(quem_bloqueou,bloqueado), CHECK(quem_bloqueou<>bloqueado));
GRANT SELECT,INSERT,DELETE ON public.bloqueios TO authenticated; GRANT ALL ON public.bloqueios TO service_role;
ALTER TABLE public.bloqueios ENABLE ROW LEVEL SECURITY;
CREATE POLICY blocks_owner ON public.bloqueios FOR SELECT TO authenticated USING(quem_bloqueou=auth.uid());
CREATE POLICY blocks_insert ON public.bloqueios FOR INSERT TO authenticated WITH CHECK(quem_bloqueou=auth.uid());
CREATE POLICY blocks_delete ON public.bloqueios FOR DELETE TO authenticated USING(quem_bloqueou=auth.uid());
CREATE TABLE public.conversas (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_a uuid NOT NULL, user_b uuid NOT NULL, criado_em timestamptz NOT NULL DEFAULT now(), CHECK(user_a<user_b), UNIQUE(user_a,user_b));
GRANT SELECT,INSERT ON public.conversas TO authenticated; GRANT ALL ON public.conversas TO service_role;
ALTER TABLE public.conversas ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.community_pair_allowed(a uuid,b uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IN (a,b) AND NOT EXISTS(SELECT 1 FROM public.bloqueios WHERE (quem_bloqueou=a AND bloqueado=b) OR (quem_bloqueou=b AND bloqueado=a)) $$;
REVOKE ALL ON FUNCTION public.community_pair_allowed(uuid,uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.community_pair_allowed(uuid,uuid) TO authenticated;
CREATE POLICY conversations_read ON public.conversas FOR SELECT TO authenticated USING(auth.uid() IN(user_a,user_b));
CREATE POLICY conversations_insert ON public.conversas FOR INSERT TO authenticated WITH CHECK(public.community_pair_allowed(user_a,user_b));
CREATE FUNCTION public.community_conversation_allowed(cid uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.conversas WHERE id=cid AND public.community_pair_allowed(user_a,user_b)) $$;
REVOKE ALL ON FUNCTION public.community_conversation_allowed(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.community_conversation_allowed(uuid) TO authenticated;
CREATE TABLE public.mensagens_privadas (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), conversa_id uuid NOT NULL REFERENCES public.conversas(id) ON DELETE CASCADE, remetente_id uuid NOT NULL, conteudo text NOT NULL CHECK(char_length(btrim(conteudo)) BETWEEN 1 AND 500), lida boolean NOT NULL DEFAULT false, criado_em timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.mensagens_privadas TO authenticated; GRANT ALL ON public.mensagens_privadas TO service_role;
ALTER TABLE public.mensagens_privadas ENABLE ROW LEVEL SECURITY;
CREATE POLICY private_read ON public.mensagens_privadas FOR SELECT TO authenticated USING(public.community_conversation_allowed(conversa_id));
CREATE POLICY private_insert ON public.mensagens_privadas FOR INSERT TO authenticated WITH CHECK(remetente_id=auth.uid() AND NOT lida AND public.community_conversation_allowed(conversa_id));
CREATE POLICY private_read_receipt ON public.mensagens_privadas FOR UPDATE TO authenticated USING(remetente_id<>auth.uid() AND public.community_conversation_allowed(conversa_id)) WITH CHECK(remetente_id<>auth.uid() AND lida AND public.community_conversation_allowed(conversa_id));
CREATE FUNCTION public.community_guard_message() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN
IF TG_OP='INSERT' THEN NEW.criado_em:=now(); NEW.conteudo:=btrim(regexp_replace(NEW.conteudo,'<[^>]*>','','g')); END IF;
IF TG_OP='UPDATE' THEN
IF TG_TABLE_NAME='mensagens_privadas' THEN IF (NEW.id,NEW.conversa_id,NEW.remetente_id,NEW.conteudo,NEW.criado_em) IS DISTINCT FROM (OLD.id,OLD.conversa_id,OLD.remetente_id,OLD.conteudo,OLD.criado_em) THEN RAISE EXCEPTION 'Only read receipts may change'; END IF;
ELSE IF (NEW.id,NEW.user_id,NEW.criado_em) IS DISTINCT FROM (OLD.id,OLD.user_id,OLD.criado_em) THEN RAISE EXCEPTION 'Message identity is immutable'; END IF; NEW.conteudo:=btrim(regexp_replace(NEW.conteudo,'<[^>]*>','','g')); END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER guard_global BEFORE INSERT OR UPDATE ON public.mensagens_globais FOR EACH ROW EXECUTE FUNCTION public.community_guard_message();
CREATE TRIGGER guard_private BEFORE INSERT OR UPDATE ON public.mensagens_privadas FOR EACH ROW EXECUTE FUNCTION public.community_guard_message();
CREATE TABLE public.denuncias (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), denunciante_id uuid NOT NULL, mensagem_id uuid NOT NULL, tipo text NOT NULL CHECK(tipo IN('global','privada')), motivo text NOT NULL CHECK(char_length(btrim(motivo)) BETWEEN 3 AND 1000), criado_em timestamptz NOT NULL DEFAULT now());
GRANT INSERT,SELECT ON public.denuncias TO authenticated; GRANT ALL ON public.denuncias TO service_role;
ALTER TABLE public.denuncias ENABLE ROW LEVEL SECURITY;
CREATE POLICY reports_insert ON public.denuncias FOR INSERT TO authenticated WITH CHECK(denunciante_id=auth.uid() AND ((tipo='global' AND EXISTS(SELECT 1 FROM public.mensagens_globais WHERE id=mensagem_id)) OR (tipo='privada' AND EXISTS(SELECT 1 FROM public.mensagens_privadas WHERE id=mensagem_id))));
CREATE POLICY reports_admin ON public.denuncias FOR SELECT TO authenticated USING(public.is_admin());
CREATE FUNCTION public.community_members() RETURNS TABLE(id uuid,display_name text,avatar_url text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT p.id,p.display_name,p.avatar_url FROM public.profiles p WHERE auth.uid() IS NOT NULL $$;
REVOKE ALL ON FUNCTION public.community_members() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.community_members() TO authenticated;
CREATE INDEX global_created ON public.mensagens_globais(criado_em DESC,id); CREATE INDEX global_user ON public.mensagens_globais(user_id);
CREATE INDEX private_conversation_created ON public.mensagens_privadas(conversa_id,criado_em DESC,id); CREATE INDEX private_sender ON public.mensagens_privadas(remetente_id); CREATE INDEX private_unread ON public.mensagens_privadas(conversa_id,lida);
CREATE INDEX conversation_a ON public.conversas(user_a); CREATE INDEX conversation_b ON public.conversas(user_b); CREATE INDEX blocks_target ON public.bloqueios(bloqueado); CREATE INDEX reports_created ON public.denuncias(criado_em);
ALTER PUBLICATION supabase_realtime ADD TABLE public.mensagens_globais,public.mensagens_privadas,public.bloqueios;
